/// <summary>
/// Extension of class <c>SalesPackingSlipDP</c>
/// </summary>
[ExtensionOf(classStr(SalesPackingSlipDP))]
final class KPMGSalesPackingSlipDP_Extension
{
}

Method.Source:
    /// <summary>
    /// Initializes a sales packing slip header.
    /// </summary>
    /// <returns>
    /// The initialized <c>SalesPackingSlipHeaderTmp</c> sales packing slip header record.
    /// </returns>
    protected SalesPackingSlipHeaderTmp initializeSalesPackingSlipHeader()
    {
        CompanyInfo               companyInfo = CompanyInfo::find();
        SalesPackingSlipHeaderTmp salesPackingSlipHeaderTmp;
        SalesTable                salesTable;
        salesPackingSlipHeaderTmp                       = next initializeSalesPackingSlipHeader();
        salesTable                                      = SalesTable::find(salesPackingSlipHeaderTmp.SalesId);
        salesPackingSlipHeaderTmp.CompanyEmail          = companyInfo.email();
        salesPackingSlipHeaderTmp.KPMGReturnItemNum     = salesTable.ReturnItemNum;
        salesPackingSlipHeaderTmp.KPMGContactPersonId   = salesTable.contactPersonName();

        Image img = CustTable::metGetCustReportLogo(this.parmCustPackingSlipJour().InvoiceAccount);
        if(img)
        {
            salesPackingSlipHeaderTmp.KPMGCompanyLogo       = img.getData();
        }
        salesPackingSlipHeaderTmp.KPMGCompanyABN            = "@MET:METABN" + companyInfo.CoRegNum;
        salesPackingSlipHeaderTmp.KPMGDeliveryDocumentNo    = this.parmCustPackingSlipJour().PackingSlipId;
        salesPackingSlipHeaderTmp.KPMGCustomerNumber        = this.parmCustPackingSlipJour().InvoiceAccount;
        salesPackingSlipHeaderTmp.KPMGShipDate              = this.parmCustPackingSlipJour().DeliveryDate;
        salesPackingSlipHeaderTmp.KPMGRouteStop             = SalesTable::find(this.parmCustPackingSlipJour().SalesId).METRouteStop;
        salesPackingSlipHeaderTmp.KPMGDeliveryInstructions  = METSalesTable::findByRefRecId(SalesTable::find(this.parmCustPackingSlipJour().SalesId).RecId).DeliveryInstructions;
        salesPackingSlipHeaderTmp.KPMGCustomerAddress       = DirUtility::replaceAddressTokenLanguage(CustTable::find(this.parmCustPackingSlipJour().InvoiceAccount).statementAddress(), CustTable::find(this.parmCustPackingSlipJour().InvoiceAccount).languageId());
        
        return salesPackingSlipHeaderTmp;
    }

    /// <summary>
    /// Initializes a sales packing slip line.
    /// </summary>
    /// <param name = "_salesPackingSlipHeaderTmp">
    /// A <c>SalesPackingSlipHeaderTmp</c> record which is the sales packing slip header.
    /// </param>
    /// <param name = "_packingSlipLineSelection">
    /// A <c>SalesPackingSlipDPPackingSlipLineQuerySelection</c> object which the sales packing slip line should be initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>SalesPackingSlipDetailsTmp</c> sales packing slip line record.
    /// </returns>
    protected SalesPackingSlipDetailsTmp initializeSalesPackingSlipLine(
        SalesPackingSlipHeaderTmp                       _salesPackingSlipHeaderTmp,
        SalesPackingSlipDPPackingSlipLineQuerySelection _packingSlipLineSelection)
    {
        SalesPackingSlipDetailsTmp salesPackingSlipTmp;

        salesPackingSlipTmp = next initializeSalesPackingSlipLine(_salesPackingSlipHeaderTmp, _packingSlipLineSelection);

        salesPackingSlipTmp.KPMGOrderNo         = _packingSlipLineSelection.parmCustPackingSlipTrans().OrigSalesId;
        salesPackingSlipTmp.KPMGUOM             = _packingSlipLineSelection.parmCustPackingSlipTrans().SalesUnit;

        return salesPackingSlipTmp;
    }
